CREATE OR ALTER PROCEDURE [dbo].[uspEmployee_GetAll] (
	@SearchText NVARCHAR(MAX) = NULL
	, @OrganizationUnitId UNIQUEIDENTIFIER = NULL
	, @PositionId UNIQUEIDENTIFIER = NULL
	, @Status NVARCHAR(MAX) = NULL
	, @CompanyId UNIQUEIDENTIFIER = NULL
	, @Code NVARCHAR(MAX) = NULL
	, @FullName NVARCHAR(MAX) = NULL
	, @DateOfBirth DATETIME2 = NULL
	, @Gender NVARCHAR(MAX) = NULL
	, @Phone NVARCHAR(MAX) = NULL
	, @Email NVARCHAR(MAX) = NULL
	, @Address NVARCHAR(MAX) = NULL
	, @HireDate DATETIME2 = NULL
	, @Page INT = 1
	, @PageSize INT = 10
	, @SortField NVARCHAR(100) = NULL
	, @SortOrder NVARCHAR(20) = NULL)
AS
BEGIN
	SET NOCOUNT ON;
	IF @Page IS NULL OR @Page < 1 SET @Page = 1;
	IF @PageSize IS NULL OR @PageSize < 1 SET @PageSize = 10;
	IF @PageSize > 1000 SET @PageSize = 1000;

	;WITH TempResult AS
	(
		SELECT
			t.[Id]
			, t.[FullName]
			, t.[OrganizationUnitId]
			, t.[PositionId]
			, t.[Phone]
			, t.[Email]
			, t.[Status]
			, t.[CompanyId]
			, t.[Code]
			, t.[DateOfBirth]
			, t.[Gender]
			, t.[Address]
			, t.[HireDate]
			, t.[CreatedDate]
		FROM [dbo].[Employee] AS t
		
		WHERE (ISNULL(@SearchText, '') = '' OR t.[FullName] LIKE CONCAT('%', @SearchText, '%') OR t.[Code] LIKE CONCAT('%', @SearchText, '%'))
			AND (@OrganizationUnitId IS NULL OR t.[OrganizationUnitId] = @OrganizationUnitId)
			AND (@PositionId IS NULL OR t.[PositionId] = @PositionId)
			AND (ISNULL(@Status, '') = '' OR t.[Status] = @Status)
			AND (@CompanyId IS NULL OR t.[CompanyId] = @CompanyId)
			AND (ISNULL(@Code, '') = '' OR t.[Code] LIKE CONCAT('%', @Code, '%'))
			AND (ISNULL(@FullName, '') = '' OR t.[FullName] LIKE CONCAT('%', @FullName, '%'))
			AND (@DateOfBirth IS NULL OR t.[DateOfBirth] = @DateOfBirth)
			AND (ISNULL(@Gender, '') = '' OR t.[Gender] LIKE CONCAT('%', @Gender, '%'))
			AND (ISNULL(@Phone, '') = '' OR t.[Phone] LIKE CONCAT('%', @Phone, '%'))
			AND (ISNULL(@Email, '') = '' OR t.[Email] LIKE CONCAT('%', @Email, '%'))
			AND (ISNULL(@Address, '') = '' OR t.[Address] LIKE CONCAT('%', @Address, '%'))
			AND (@HireDate IS NULL OR t.[HireDate] = @HireDate)
			AND t.IsDeleted = 0
	),
	TempCount (TotalRow) AS (SELECT COUNT(*) FROM TempResult)
	SELECT r.*, c.TotalRow
	FROM TempResult AS r CROSS JOIN TempCount AS c
	ORDER BY
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'fullName' THEN r.[FullName] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'fullName' THEN r.[FullName] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'organizationUnitId' THEN r.[OrganizationUnitId] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'organizationUnitId' THEN r.[OrganizationUnitId] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'positionId' THEN r.[PositionId] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'positionId' THEN r.[PositionId] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'phone' THEN r.[Phone] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'phone' THEN r.[Phone] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'email' THEN r.[Email] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'email' THEN r.[Email] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'status' THEN r.[Status] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'status' THEN r.[Status] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'companyId' THEN r.[CompanyId] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'companyId' THEN r.[CompanyId] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'code' THEN r.[Code] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'code' THEN r.[Code] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'dateOfBirth' THEN r.[DateOfBirth] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'dateOfBirth' THEN r.[DateOfBirth] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'gender' THEN r.[Gender] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'gender' THEN r.[Gender] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'address' THEN r.[Address] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'address' THEN r.[Address] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'hireDate' THEN r.[HireDate] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'hireDate' THEN r.[HireDate] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'createdDate' THEN r.[CreatedDate] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'createdDate' THEN r.[CreatedDate] END DESC,
		r.[CreatedDate] DESC
	OFFSET (@PageSize * (@Page - 1)) ROWS FETCH NEXT @PageSize ROWS ONLY
	OPTION (RECOMPILE);
END
